class Solution:
    def maxProfit(self, k: int, prices: List[int]) -> int:
        n = len(prices)
        def best(i, left, holding):
            if i == n or left == 0:
                return 0
            skip = best(i + 1, left, holding)
            if holding:
                act = prices[i] + best(i + 1, left - 1, False)
            else:
                act = -prices[i] + best(i + 1, left, True)
            return max(skip, act)
        return best(0, k, False)

