class Solution:
    def minSessions(self, tasks: List[int], sessionTime: int) -> int:
        n = len(tasks)
        full = 1 << n
        total = [0] * full
        for mask in range(1, full):
            low = mask & -mask
            total[mask] = total[mask ^ low] + tasks[low.bit_length() - 1]
        dp = [0] * full
        for mask in range(1, full):
            best, sub = n, mask
            while sub:
                if total[sub] <= sessionTime and dp[mask ^ sub] + 1 < best:
                    best = dp[mask ^ sub] + 1
                sub = (sub - 1) & mask
            dp[mask] = best
        return dp[-1]

