class Solution {
    public int shortestPathLength(int[][] graph) {
        int n = graph.length, full = (1 << n) - 1;
        boolean[][] seen = new boolean[n][1 << n];
        ArrayDeque<int[]> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            seen[i][1 << i] = true;
            q.add(new int[] { i, 1 << i, 0 });
        }
        while (!q.isEmpty()) {
            int[] s = q.poll();
            if (s[1] == full) return s[2];
            for (int v : graph[s[0]]) {
                int mask = s[1] | 1 << v;
                if (!seen[v][mask]) {
                    seen[v][mask] = true;
                    q.add(new int[] { v, mask, s[2] + 1 });
                }
            }
        }
        return 0;
    }
}

